    color += (sparkle + slopeGlint) * vec3(1.0, 0.94, 0.82);
    color = mix(color, u_foamColor.rgb, crest);
    color = czm_gammaCorrect(color);
    out_FragColor = vec4(color, clamp(u_alpha + crest * 0.14, 0.0, 1.0));
